<template><section><header class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><h1 class="page-title mb-1">Quản lý khóa học</h1><p class="page-subtitle mb-0">Tạo, xuất bản và quản lý nội dung đào tạo.</p></div><button class="btn btn-brand" @click="showForm=true"><i class="bi bi-plus-lg me-1"></i> Thêm khóa học</button></header><div class="app-card p-3 mb-3"><div class="row g-2"><div class="col-md-6"><input v-model="search" class="form-control" placeholder="Tìm kiếm khóa học..."></div><div class="col-md-3"><select class="form-select"><option>Tất cả giảng viên</option><option>Nguyễn Văn Giảng</option></select></div><div class="col-md-3"><select class="form-select"><option>Tất cả trạng thái</option><option>Đã xuất bản</option><option>Bản nháp</option></select></div></div></div><div class="app-card p-2"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Khóa học</th><th>Giảng viên</th><th>Học viên</th><th>Bài học</th><th>Trạng thái</th><th class="text-end">Thao tác</th></tr></thead><tbody><tr v-for="course in filtered" :key="course.id"><td><div class="d-flex align-items-center gap-2"><span class="course-thumb" :style="{background:course.color}"><i class="bi bi-code-slash"></i></span><div><strong>{{ course.title }}</strong><small class="d-block text-secondary">{{ course.code }} • {{ course.category }}</small></div></div></td><td>{{ course.teacher }}</td><td>{{ course.students }}</td><td>{{ course.lessons }}</td><td><span :class="['badge',course.status==='PUBLISHED'?'badge-soft-success':'badge-soft-warning']">{{ course.status==='PUBLISHED'?'Đã xuất bản':'Bản nháp' }}</span></td><td class="text-end"><RouterLink class="btn btn-light btn-sm me-1" :to="`/cms/courses/${course.id}/content`"><i class="bi bi-list-task"></i></RouterLink><button class="btn btn-light btn-sm"><i class="bi bi-three-dots"></i></button></td></tr></tbody></table></div></div><div v-if="showForm" class="modal-mask" @click.self="showForm=false"><form class="app-card form-modal" @submit.prevent="addCourse"><div class="d-flex justify-content-between"><h2 class="h4 fw-bold">Thêm khóa học</h2><button type="button" class="btn-close" @click="showForm=false"></button></div><div class="row g-3 mt-1"><div class="col-md-4"><label class="form-label">Mã khóa học</label><input v-model="form.code" class="form-control" required></div><div class="col-md-8"><label class="form-label">Tên khóa học</label><input v-model="form.title" class="form-control" required></div><div class="col-12"><label class="form-label">Mô tả ngắn</label><textarea class="form-control" rows="3"></textarea></div><div class="col-md-6"><label class="form-label">Giảng viên</label><select class="form-select"><option>Nguyễn Văn Giảng</option></select></div><div class="col-md-6"><label class="form-label">Trình độ</label><select class="form-select"><option>Cơ bản</option><option>Trung cấp</option></select></div></div><div class="d-flex justify-content-end gap-2 mt-4"><button type="button" class="btn btn-light" @click="showForm=false">Hủy</button><button class="btn btn-brand">Tạo khóa học</button></div></form></div></section></template>
<script setup>import { computed,reactive,ref } from 'vue';import { courses } from '../../data/demo';const items=ref([...courses]),search=ref(''),showForm=ref(false),form=reactive({code:'',title:''});const filtered=computed(()=>items.value.filter(c=>`${c.title} ${c.code}`.toLowerCase().includes(search.value.toLowerCase())));function addCourse(){items.value.unshift({id:Date.now(),code:form.code,title:form.title,teacher:'Nguyễn Văn Giảng',category:'Chưa phân loại',students:0,lessons:0,status:'DRAFT',color:'#005099'});showForm.value=false}</script>
<style scoped>.course-thumb{width:50px;height:42px;border-radius:8px;display:grid;place-items:center;color:white;font-size:1.2rem}.modal-mask{position:fixed;inset:0;background:rgba(10,31,24,.55);display:grid;place-items:center;z-index:2000;padding:1rem}.form-modal{width:min(700px,100%);padding:1.5rem}</style>
